 t['hero']=tri('پژوهش را دقیق‌تر بیاموزید.<br><span>از ایده تا پایان‌نامه و مقاله.</span>','Make better research decisions.<br><span>From an idea to a thesis and paper.</span>','تعلم البحث بدقة أكبر.<br><span>من الفكرة إلى الأطروحة والمقال.</span>')[lang]
 t['intro']=tri(f'{count} راهنمای آموزشی با منبع، مثال و کاربرگ در فارسی، انگلیسی و عربی؛ مسیرهای یادگیری برای طراحی، تحلیل، نگارش و انتشار مسئولانه پژوهش.',f'{count} sourced learning guides with examples and workbooks in Persian, English and Arabic, plus learning paths for design, analysis, writing and responsible publication.',f'{count} دليلاً تعليمياً بمصادر وأمثلة ودفاتر عمل بالفارسية والإنجليزية والعربية ومسارات للتصميم والتحليل والكتابة والنشر المسؤول.')[lang]
 t['knowdesc']=tri(f'{count} راهنما را بر اساس سؤال، روش یا مرحله پژوهش پیدا کنید. مثال‌های فرضی، کاربرگ‌های قابل ویرایش و پیوند منابع اصلی به تصمیم بهتر کمک می‌کنند.',f'Find {count} guides by question, method or stage. Fictional worked cases, editable workbooks and original-source links support better decisions.',f'اعثر على {count} دليلاً بالسؤال أو المنهج أو المرحلة مع حالات افتراضية ودفاتر قابلة للتحرير وروابط الأصول.')[lang]
 t['search']=tri(f'جست‌وجو در {count} راهنما بر اساس موضوع، روش یا ابزار',f'Search {count} guides by topic, method or tool',f'ابحث في {count} دليلاً بالموضوع أو المنهج أو الأداة')[lang]
 t['pill']=tri(['سه زبان؛ منابع اصلی','مثال‌های آموزشی با مرز روشن','کاربرگ و کد قابل بررسی'],['Three languages · Primary sources','Clearly labeled teaching examples','Reviewable workbooks and code'],['ثلاث لغات · مصادر أصلية','أمثلة تعليمية موضحة','دفاتر وكود قابلان للفحص'])[lang]
 t['learningpaths']=tri('مسیرهای یادگیری','Learning paths','مسارات التعلم')[lang]
