 t['updated']=tri('ویرایش محتوایی: ۶ اکتبر ۲۰۲۶','Content revision: October 6, 2026','تعديل المحتوى: 6 أكتوبر 2026')[lang]
 D['meta'][lang]['']= [tri('آموزش پژوهش، پایان‌نامه و مقاله','Research methods, theses and papers','تعلم البحث والأطروحات والمقالات')[lang],tri('راهنماهای پژوهش با منبع، مثال و کاربرگ؛ مسیرهای یادگیری طراحی، تحلیل، نگارش و انتشار در فارسی، انگلیسی و عربی.', 'Sourced research guides, worked examples and editable workbooks, with study paths for design, analysis, writing and publication in three languages.', 'أدلة بحث بمصادر وأمثلة ودفاتر عمل ومسارات للتصميم والتحليل والكتابة والنشر بثلاث لغات.')[lang]]
 D['meta'][lang]['guides']=[tri(f'{count} راهنمای پژوهش با مثال و کاربرگ',f'{count} research guides with examples and workbooks',f'{count} دليلاً بحثياً مع أمثلة ودفاتر عمل')[lang],t['knowdesc']]
 D['meta'][lang]['learning-paths']=[t['learningpaths'],tri('هشت مسیر گام‌به‌گام برای طرح، شواهد، تحلیل، داده، نگارش و انتشار؛ هر مسیر به راهنما و خروجی مشخص پیوند دارد.','Eight study paths for design, evidence, analysis, data, writing and publishing, each linked to guides and concrete deliverables.','ثمانية مسارات للتصميم والأدلة والتحليل والبيانات والكتابة والنشر مرتبطة بالأدلة والمخرجات.')[lang]]
 D['meta'][lang]['glossary']=[t['glossary'],tri(f'{len(GLOSSARY)} اصطلاح پژوهشی با تعریف کوتاه، معادل انگلیسی و پیوند آموزش کاربردی؛ از CI و TOST تا FAIR و گزارش ثبت‌شده.',f'{len(GLOSSARY)} research terms with concise definitions and practical guide links, from CI and TOST to FAIR and Registered Reports.',f'{len(GLOSSARY)} مصطلحاً بتعريف موجز وروابط تطبيقية من CI وTOST إلى FAIR والتقارير المسجلة.')[lang]]
 D['meta'][lang]['resources'][1]=tri(f'{len(D["resources"])} منبع رسمی و علمی برای کشف، روش، شفافیت و انتشار؛ شرایط دسترسی و دامنه هر منبع مشخص است.',f'{len(D["resources"])} official and scholarly resources for discovery, methods, transparency and publication, with scope and access notes.',f'{len(D["resources"])} مصدراً رسمياً وعلمياً للاكتشاف والمنهج والشفافية والنشر مع ملاحظات النطاق والوصول.')[lang]
 D['meta'][lang]['toolkit'][1]=tri('کاربرگ هر راهنما، الگوهای قابل ویرایش، کد و دادۀ ساختگی قابل بازاجرا، سازندۀ پیوند DOI و برنامه‌ریز پژوهش.','Guide workbooks, editable templates, reproducible synthetic data and code, a DOI link builder and a research planner.','دفاتر الأدلة وقوالب وكود وبيانات اصطناعية متكررة وأداة DOI ومخطط بحث.')[lang]
 for a in D['articles'][lang]:
  a['body']=a['body'].replace('كود وبيانات تعليمية وخروجی بازاجرای شش مسیر.','کد و داده آموزشی و خروجی بازاجرای شش مسیر.').replace('p_TO\u200bST','p_TOST').replace('بنابراین در این مدل آموزشی هم‌ارزی رد نمی‌شود، بلکه فرضِ بیرون‌بودن از حدود رد و هم‌ارزی پشتیبانی می‌شود.','بنابراین در این مدل آموزشی، هر دو فرض نامعادل‌بودن رد و هم‌ارزی پشتیبانی می‌شود.')
  if a['slug'] in ('research-programming','reproducible-notebooks','multiverse-analysis','computational-thesis-quarto','equivalence-testing','data-papers','research-software-papers'):
   a['downloads'].append({'file':'common/research-examples.zip','label':tri('کد، دادۀ ساختگی و مثال‌های اجرایی','Code, synthetic data and executable examples','كود وبيانات اصطناعية وأمثلة تنفيذية')[lang]})
  a['search_terms']=' '.join(g['title']['en'] for g in GLOSSARY if g['guide']==a['slug'])
  a['paths']=[p['id'] for p in PATHS if a['slug'] in p['guides']]
  assert all(s in D['source_registry'] for s in a['sources']), (lang,a['slug'],'unknown source')
  assert all(s in {x['slug'] for x in D['articles'][lang]} for s in a['related']), (lang,a['slug'],'unknown related guide')
